AUnmadeTravelingProjectile::AUnmadeTravelingProjectile(){PrimaryActorTick.bCanEverTick=true;Visual=CreateDefaultSubobject<UStaticMeshComponent>(TEXT("TravelingShot"));SetRootComponent(Visual);Visual->SetCollisionEnabled(ECollisionEnabled::NoCollision);Visual->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Sphere.Sphere")));Visual->SetRelativeScale3D(FVector(.13));}
bool AUnmadeTravelingProjectile::Fire(AActor* Source,const FVector& Aim,double Amount,uint64 Id,float Speed,float Range,UnmadeCore::CombatStatus Status){if(!GetWorld()||!IsValid(Source)||!Id||!FMath::IsFinite(Amount)||Amount<=0||!FMath::IsFinite(Range)||Range<100||Range>4000||!UnmadeCore::ProjectileFlightValid(Speed,Range/Speed)){Destroy();return false;}auto direction=(Aim-GetActorLocation()).GetSafeNormal();if(direction.IsNearlyZero()){Destroy();return false;}ShotStatus=Status;Shooter=Source;Damage=Amount;Receipt=Id;Velocity=direction*Speed;Expires=GetWorld()->GetTimeSeconds()+Range/Speed;return true;}
void AUnmadeTravelingProjectile::Tick(float Delta){Super::Tick(Delta);if(!GetWorld()||!Shooter.IsValid()||GetWorld()->GetTimeSeconds()>Expires){Destroy();return;}FVector from=GetActorLocation(),to=from+Velocity*(FMath::IsFinite(Delta)?FMath::Max(0.f,Delta):0.f);FCollisionQueryParams q(SCENE_QUERY_STAT(TravelingProjectile),false);q.AddIgnoredActor(this);q.AddIgnoredActor(Shooter.Get());FCollisionObjectQueryParams objects;objects.AddObjectTypesToQuery(ECC_Pawn);objects.AddObjectTypesToQuery(ECC_WorldStatic);objects.AddObjectTypesToQuery(ECC_WorldDynamic);FHitResult hit;
 if(GetWorld()->SweepSingleByObjectType(hit,from,to,FQuat::Identity,objects,FCollisionShape::MakeSphere(12),q)){if(auto* actor=hit.GetActor())if(auto* combat=actor->FindComponentByClass<UUnmadeCombatComponent>()){float before=combat->GetHealth();if(combat->ReceiveTravelingHit(Shooter.Get(),Receipt,Damage,GetWorld()->GetTimeSeconds())){if(ShotStatus!=UnmadeCore::CombatStatus::None){combat->ApplyStatus(ShotStatus,4,Shooter.Get());combat->Stagger(GetWorld()->GetTimeSeconds(),.65);}if(auto* e=Cast<AUnmadeEnemyCharacter>(actor)){if(auto* p=Cast<AUnmadeCharacter>(Shooter.Get()))p->NotifyProjectileImpact(e,before);else e->NotifyPlayerHit(before-combat->GetHealth());}}}Destroy();return;}SetActorLocation(to,false);}
